html:
{% set company = frappe.get_doc("Company", doc.company) %}
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        @page {
            size: A4;
            margin: 15mm;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: Arial, sans-serif;
            font-size: 11pt;
            color: #000;
            line-height: 1.4;
        }

        .container {
            width: 100%;
            padding: 20px;
        }

        .header {
            margin-bottom: 30px;
        }

        .header img {
            height: 60px;
        }

        .title {
            font-size: 16pt;
            font-weight: bold;
            border-bottom: 2px solid #000;
            padding-bottom: 8px;
            margin: 20px 0 15px 0;
        }

        .subtitle {
            font-weight: bold;
            margin-bottom: 20px;
        }

        .page-number {
            text-align: right;
            margin-bottom: 15px;
            font-size: 10pt;
        }

        .main-table {
            width: 100%;
            border-collapse: collapse;
            margin: 20px 0;
            font-size: 9pt;
        }

        .main-table th {
            background-color: #f0f0f0;
            border: 1px solid #000;
            padding: 8px;
            font-weight: bold;
            text-align: center;
            vertical-align: middle;
        }

        .main-table td {
            border: 1px solid #000;
            padding: 6px 8px;
            vertical-align: top;
        }

        .main-table td.right-align {
            text-align: right;
        }

        .main-table td.center-align {
            text-align: center;
        }

        .main-table tr.total-row {
            font-weight: bold;
        }

        .main-table tr.total-row td {
            background-color: #f9f9f9;
        }

        .certification {
            margin-top: 80px;
            position: relative;
        }

        .certification p {
            display: inline-block;
        }

        .stamp-image {
            display: inline-block;
            margin-left: 30px;
            vertical-align: middle;
        }

        .stamp-image img {
            height: 70px;
        }

        .signature-section {
            margin-top: 60px;
            font-weight: bold;
        }

        .footer {
            text-align: center;
            margin-top: 80px;
            font-size: 8pt;
            line-height: 1.6;
        }

        .footer p {
            margin: 0;
        }
    </style>
</head>
<body>
<div class="container">
    <!-- Header with logo -->
    <div class="header">
        {% if company.company_logo %}
        <img src="{{ company.company_logo }}" alt="Company Logo">
        {% endif %}
    </div>

    <!-- Title -->
    <div class="title">HS Code Classification</div>

    <!-- Subtitle -->
    <div class="subtitle">Dubai Ports and Customs Free Zone Corporation</div>


    <!-- Main classification table -->
    <table class="main-table">
    {% set ns = namespace(data={}) %}

    {# ---- Build COO-wise consolidated data ---- #}
    {% for item in doc.items %}
        {% set key = item.coo or "N/A" %}
        {% if key not in ns.data %}
            {% set ns.data = ns.data.update({
                key: {
                    "hs_code": item.hs_code,
                    "description": item.item_code,
                    "qty": item.qty or 0,
                    "gross_wt": item.gross_wt or 0,
                    "total_value": item.total_value or 0
                }
            }) or ns.data %}
        {% else %}
            {% set ns.data = ns.data.update({
                key: {
                    "hs_code": ns.data[key].hs_code,
                    "description": ns.data[key].description,
                    "qty": ns.data[key].qty + (item.qty or 0),
                    "gross_wt": ns.data[key].gross_wt + (item.gross_wt or 0),
                    "total_value": ns.data[key].total_value + (item.total_value or 0)
                }
            }) or ns.data %}
        {% endif %}
    {% endfor %}

    <thead>
        <tr>
            <th style="width:12%;">HTS Code</th>
            <th style="width:30%;">Goods Description</th>
            <th style="width:10%;">Country of Origin</th>
            <th style="width:8%;">Qty</th>
            <th style="width:10%;">Weight</th>
            <th style="width:12%;">Currency Value</th>
        </tr>
    </thead>

    <tbody>
        {% for coo, row in ns.data.items() %}
        <tr>
            <td class="center-align">{{ row.hs_code }}</td>
            <td>{{ row.description }}</td>
            <td class="center-align">{{ coo }}</td>
            <td class="right-align">{{ row.qty }}</td>
            <td class="right-align">{{ "%.4f"|format(row.gross_wt) }}</td>
            <td class="right-align">{{ "{:,.2f}".format(row.total_value) }}</td>
        </tr>
        {% endfor %}

        <!-- Grand Total -->
        <tr class="total-row">
            <td colspan="3" class="right-align"><b>Total :</b></td>
            <td class="right-align"><b>{{ doc.total_qty }}</b></td>
            <td class="right-align"><b>{{ "%.4f"|format(doc.total_gross_wt) }}</b></td>
            <td class="right-align"><b>{{ "{:,.2f}".format(doc.total_value) }}</b></td>
        </tr>
    </tbody>
</table>


    <!-- Certification section -->
    <div class="certification">
        <p>I certify the information above is correct</p>
        <div class="stamp-image">
            {% if company.company_logo %}
            <img src="{{ company.company_logo }}" alt="Stamp">
            {% endif %}
        </div>
    </div>

    <!-- Signature section -->
    <div class="signature-section">
        <p>Consignee Signature and Stamp</p>
    </div>

    <!-- Footer -->
    <div class="footer">
        <p>

        </p>
    </div>
</div>
</body>
</html>
